// ─────────────────────────────────────────────────────────────
// BRAID WATCHES — settings
//
// ON VERCEL you do NOT edit this file. Set these in
// Vercel → Project → Settings → Environment Variables, then redeploy:
//
//   ADMIN_PASSCODE     your password for the "Staff login" button
//   WHATSAPP_NUMBER    digits only with country code, no "+"  (2348012345678)
//   TELEGRAM_USERNAME  without the "@"
//   ADMIN_SECRET       optional, any long random text
//
// plus a database: Vercel → Storage → Create → Upstash Redis → connect it to
// this project (it adds the database variables for you).
//
// The page reads the chat numbers from /api/config, so they update the
// WhatsApp / Telegram buttons everywhere without touching code.
//
// The values below are only used when previewing the app without Vercel.
// The preview passcode is NOT secure, so never rely on it for the live site.
// ─────────────────────────────────────────────────────────────

const env = (typeof window !== 'undefined' && window.__BRAID_ENV__) || {};

export const CONFIG = {
  whatsappNumber: String(env.WHATSAPP_NUMBER || '').replace(/\D/g, ''),
  telegramUsername: String(env.TELEGRAM_USERNAME || '').replace(/^@/, ''),
  adminPasscode: String(env.ADMIN_PASSCODE ?? 'Braid#2026'), // preview only
  usdToNgn: 1550, // converts the sample watches' old dollar prices into Naira
  // How many Naira one unit of local money is worth. Only used to show buyers an approximate
  // price in Rand, Shillings or Cedis. Update these when rates move; the merchant confirms the final amount.
  ngnPer: { ZAR: 85, KES: 12, GHS: 135 },
  timeZone: 'Africa/Lagos',
  timeZoneLabel: 'WAT',
};

export const isChatConfigured = () => Boolean(CONFIG.whatsappNumber || CONFIG.telegramUsername);
